('age','trees','single',null,'{"gu":"આંબા કેટલા વર્ષના છે?","hi":"पेड़ कितने साल के हैं?","en":"How old are the trees?"}'::jsonb,'[{"value":"0-1","gu":"0-1","hi":"0-1","en":"0-1"},{"value":"1-2","gu":"1-2","hi":"1-2","en":"1-2"},{"value":"2-4","gu":"2-4","hi":"2-4","en":"2-4"},{"value":"4-7","gu":"4-7","hi":"4-7","en":"4-7"},{"value":"7-12","gu":"7-12","hi":"7-12","en":"7-12"},{"value":"12-20","gu":"12-20","hi":"12-20","en":"12-20"},{"value":"20-30","gu":"20-30","hi":"20-30","en":"20-30"},{"value":"30-40","gu":"30-40","hi":"30-40","en":"30-40"},{"value":"40-50","gu":"40-50","hi":"40-50","en":"40-50"},{"value":"50-60","gu":"50-60","hi":"50-60","en":"50-60"},{"value":"60+","gu":"60+","hi":"60+","en":"60+"}]'::jsonb,0),
