('variety','trees','single','optional','{"gu":"કઈ જાત?","hi":"कौन सी किस्म?","en":"Which variety?"}'::jsonb,'[{"value":"kesar","gu":"કેસર","hi":"केसर","en":"Kesar"},{"value":"alphonso","gu":"હાફૂસ","hi":"हापुस (अल्फांसो)","en":"Alphonso"},{"value":"rajapuri","gu":"રાજાપુરી","hi":"राजापुरी","en":"Rajapuri"},{"value":"other","gu":"બીજી / મિક્સ","hi":"अन्य / मिक्स","en":"Other / mixed"}]'::jsonb,2),
('problems','see','multi',null,'{"gu":"બગીચામાં શું દેખાય છે?","hi":"बाग़ में क्या दिख रहा है?","en":"What do you see in the orchard?"}'::jsonb,'[{"value":"flowering","gu":"ફૂલ (મોર) ઓછાં આવે છે","hi":"बौर कम आता है","en":"Few flowers"},{"value":"drop","gu":"ફૂલ આવે, ફળ ખરી જાય","hi":"फल गिर जाते हैं","en":"Fruit drops"},{"value":"small","gu":"ફળ નાનાં રહે છે","hi":"फल छोटे रहते हैं","en":"Small fruit"},{"value":"alternate","gu":"એક વર્ષ પાક, બીજે વર્ષ ઓછો","hi":"एक साल फसल, अगले साल कम","en":"Good one year, poor the next"},{"value":"pest","gu":"મોર પર ચીકાશ કે સફેદ ભૂકી","hi":"बौर पर चिपचिपाहट या सफ़ेद पाउडर","en":"Sticky or white powder on flowers"},{"value":"dying","gu":"આંબો કે ડાળી સુકાય છે","hi":"पेड़ या डाली सूख रही है","en":"Tree or branch drying"},{"value":"yellow","gu":"પાન પીળાં / આંબો નબળો","hi":"पत्ते पीले / पेड़ कमज़ोर","en":"Yellow leaves / weak tree"},{"value":"noProduction2","gu":"2 વર્ષથી પાક નથી","hi":"2 साल से फसल नहीं","en":"No crop for 2 years"},{"value":"none","gu":"હાલ કોઈ મોટી તકલીફ નથી","hi":"अभी कोई बड़ी समस्या नहीं","en":"No major problem now"}]'::jsonb,3),
('dryWhere','details','single','problems has dying','{"gu":"સુકારો ક્યાંથી શરૂ થયો?","hi":"सूखना कहाँ से शुरू हुआ?","en":"Where did the drying start?"}'::jsonb,'[{"value":"tip","gu":"ડાળીની ટોચથી નીચે તરફ","hi":"डाली के सिरे से नीचे की ओर","en":"From branch tips downwards"},{"value":"trunk","gu":"થડમાં કાણાં, નીચે લાકડાનો ભૂકો","hi":"तने में छेद, नीचे बुरादा","en":"Holes in the trunk, sawdust below"},{"value":"whole","gu":"આખો આંબો ઝાંખો, પાન પીળાં","hi":"पूरा पेड़ मुरझाया, पत्ते पीले","en":"Whole tree pale, leaves yellow"},{"value":"oneSide","gu":"એક બાજુની ડાળીઓ","hi":"एक तरफ़ की डालियाँ","en":"Branches on one side"}]'::jsonb,4),
('leavesInstead','details','single','problems has flowering','{"gu":"મોરને બદલે નવાં લાલ-કુમળાં પાન આવે છે?","hi":"बौर की जगह नई लाल-कोमल पत्तियाँ आती हैं?","en":"Do new red leaves come instead of flowers?"}'::jsonb,'[{"value":"yes","gu":"હા","hi":"हाँ","en":"Yes"},{"value":"no","gu":"ના","hi":"नहीं","en":"No"},{"value":"notSure","gu":"ખબર નથી","hi":"पता नहीं","en":"Not sure"}]'::jsonb,5),
('dropSize','details','single','problems has drop','{"gu":"ફળ ખરે ત્યારે કેવડાં હોય છે?","hi":"गिरते समय फल कितने बड़े होते हैं?","en":"How big are the fruits when they drop?"}'::jsonb,'[{"value":"tiny","gu":"રાઈ-વટાણા જેવડાં","hi":"सरसों-मटर जितने","en":"Mustard to pea size"},{"value":"marble","gu":"લખોટી જેવડાં","hi":"कंचे जितने","en":"Marble size"},{"value":"big","gu":"મોટાં ફળ","hi":"बड़े फल","en":"Big fruit"}]'::jsonb,6),
('pestSign','details','single','problems has pest','{"gu":"મોર પર શું દેખાય છે?","hi":"बौर पर क्या दिखता है?","en":"What do you see on the flowers?"}'::jsonb,'[{"value":"sticky","gu":"ચીકાશ, નાનાં ઊડતાં જીવડાં","hi":"चिपचिपाहट, छोटे उड़ते कीड़े","en":"Sticky, tiny jumping insects"},{"value":"white","gu":"સફેદ લોટ જેવી ભૂકી","hi":"सफ़ेद आटे जैसा पाउडर","en":"White flour-like powder"},{"value":"both","gu":"બંને","hi":"दोनों","en":"Both"},{"value":"notSure","gu":"ખબર નથી","hi":"पता नहीं","en":"Not sure"}]'::jsonb,7),
('yellowWhere','details','single','problems has yellow','{"gu":"પીળાશ ક્યાં છે?","hi":"पीलापन कहाँ है?","en":"Where is the yellowing?"}'::jsonb,'[{"value":"newLeaves","gu":"નવાં પાનમાં","hi":"नई पत्तियों में","en":"On new leaves"},{"value":"oldLeaves","gu":"જૂનાં, નીચેનાં પાનમાં","hi":"पुरानी, नीचे की पत्तियों में","en":"On old, lower leaves"},{"value":"whole","gu":"આખા આંબામાં","hi":"पूरे पेड़ में","en":"The whole tree"}]'::jsonb,8),
