('treeLooks','details','single','problems has noProduction2','{"gu":"પાક વગરનો આંબો કેવો દેખાય છે?","hi":"बिना फसल का पेड़ कैसा दिखता है?","en":"How does the tree without a crop look?"}'::jsonb,'[{"value":"leafy","gu":"લીલોછમ, પાન ભરપૂર","hi":"हरा-भरा, पत्ते भरपूर","en":"Green and leafy"},{"value":"weak","gu":"નબળો, ડાળીઓ સુકાય","hi":"कमज़ोर, डालियाँ सूखती","en":"Weak, branches drying"}]'::jsonb,10),
('bearing','history','single',null,'{"gu":"દર વર્ષે ફૂલ અને પાક આવે છે?","hi":"हर साल बौर और फसल आती है?","en":"Do flowers and a crop come every year?"}'::jsonb,'[{"value":"regular","gu":"હા, દર વર્ષે નિયમિત","hi":"हाँ, हर साल नियमित","en":"Yes, regular every year"},{"value":"inconsistent","gu":"ફૂલ આવે છે, પણ ઉત્પાદન સ્થિર નથી","hi":"फूल आते हैं, पर उत्पादन स्थिर नहीं","en":"Flowers come, but production is uneven"},{"value":"sometimes","gu":"કોઈ વર્ષ સારું, કોઈ વર્ષ નબળું","hi":"कोई साल अच्छा, कोई साल कम","en":"Some years good, some poor"},{"value":"misses","gu":"ઘણી વાર પાક ચૂકી જાય છે","hi":"कई बार फसल छूट जाती है","en":"Often misses a crop year"},{"value":"noProduction2","gu":"2 વર્ષથી યોગ્ય પાક નથી","hi":"2 साल से सही फसल नहीं","en":"No proper crop for 2 years"},{"value":"young","gu":"હજુ પાક લેવાની ઉંમર નથી","hi":"अभी फसल की उम्र नहीं","en":"Trees are too young to bear"}]'::jsonb,11),
('cultar','history','single',null,'{"gu":"Cultar / Paclobutrazol વાપરો છો?","hi":"कल्टार / पैक्लोबुट्राज़ोल इस्तेमाल करते हैं?","en":"Do you use Cultar / Paclobutrazol?"}'::jsonb,'[{"value":"regular","gu":"હા, નિયમિત","hi":"हाँ, नियमित","en":"Yes, regularly"},{"value":"occasionally","gu":"હા, ક્યારેક","hi":"हाँ, कभी-कभी","en":"Yes, sometimes"},{"value":"no","gu":"ના","hi":"नहीं","en":"No"},{"value":"notSure","gu":"ખબર નથી","hi":"पता नहीं","en":"Not sure"}]'::jsonb,12),
('cultarYears','history','number','cultar is regular or occasionally','{"gu":"કેટલા વર્ષથી?","hi":"कितने साल से?","en":"For how many years?"}'::jsonb,'[]'::jsonb,13),
('irrigation','care','single',null,'{"gu":"પિયત કેવી રીતે આપો છો?","hi":"सिंचाई कैसे करते हैं?","en":"How do you irrigate?"}'::jsonb,'[{"value":"drip","gu":"ટપક","hi":"ड्रिप","en":"Drip"},{"value":"flood","gu":"ખુલ્લું / રેલાવીને","hi":"खुला / बहाकर","en":"Flood / basin"},{"value":"rainfed","gu":"વરસાદ આધારિત","hi":"बारिश पर निर्भर","en":"Rain-fed only"}]'::jsonb,14),
('waterNow','care','single','month Oct-Jan and trees bearing','{"gu":"હાલ મોટા આંબાને પિયત ચાલુ છે?","hi":"अभी बड़े पेड़ों में सिंचाई चल रही है?","en":"Are you watering bearing trees now?"}'::jsonb,'[{"value":"yes","gu":"હા","hi":"हाँ","en":"Yes"},{"value":"no","gu":"ના, બંધ છે","hi":"नहीं, बंद है","en":"No, stopped"}]'::jsonb,15),
('soil','care','multi',null,'{"gu":"છેલ્લાં વર્ષોમાં આમાંથી શું વધુ વાપર્યું?","hi":"पिछले सालों में क्या ज़्यादा इस्तेमाल किया?","en":"Which have you used a lot in recent years?"}'::jsonb,'[{"value":"fungicides","gu":"ફૂગનાશક","hi":"फफूंदनाशक","en":"Fungicides"},{"value":"weedicides","gu":"નીંદણનાશક","hi":"खरपतवारनाशक","en":"Weedicides"},{"value":"insecticides","gu":"જંતુનાશક","hi":"कीटनाशक","en":"Insecticides"},{"value":"rare","gu":"બહુ ઓછો ઉપયોગ","hi":"बहुत कम उपयोग","en":"Very little"},{"value":"notSure","gu":"ખબર નથી","hi":"पता नहीं","en":"Not sure"}]'::jsonb,16)
insert into public.mango_causes(key,guide,title,why,actions,urgent) values
('borer','drying-trees','{"gu":"થડ કોરી ખાનારી ઈયળ","hi":"तना छेदक इल्ली","en":"Stem borer"}'::jsonb,'{"gu":"થડમાં કાણાં અને લાકડાનો ભૂકો એ તેની નિશાની છે.","hi":"तने में छेद और बुरादा इसकी निशानी है.","en":"Holes and sawdust on the trunk point to it."}'::jsonb,'{"gu":["કાણાં અને થડનો નજીકનો ફોટો આજે જ મોકલો","નિષ્ણાતની સલાહ પ્રમાણે સારવાર, મોડું ન કરો"],"hi":["छेद और तने का नज़दीकी फ़ोटो आज ही भेजें","विशेषज्ञ की सलाह से इलाज, देर न करें"],"en":["Send a close photo of the holes today","Treat as advised by an expert, without delay"]}'::jsonb,true),
('dieback','drying-trees','{"gu":"ડાળીનો સુકારો (ફૂગ)","hi":"डाली का सूखा रोग (फफूंद)","en":"Dieback (fungal)"}'::jsonb,'{"gu":"ડાળી ટોચથી નીચે તરફ સુકાય છે.","hi":"डाली सिरे से नीचे सूख रही है.","en":"Branches dry from the tip downwards."}'::jsonb,'{"gu":["સુકી ડાળી તંદુરસ્ત ભાગ સુધી કાપી બાળી નાખો","કાપ પર ભલામણ કરેલી પેસ્ટ લગાવો"],"hi":["सूखी डाली स्वस्थ हिस्से तक काटकर जला दें","कटे हिस्से पर सुझाया गया लेप लगाएँ"],"en":["Cut dry branches back to healthy wood and burn them","Apply a recommended paste on the cuts"]}'::jsonb,true),
('roots','drying-trees','{"gu":"મૂળ કે જમીનની તકલીફ","hi":"जड़ या मिट्टी की समस्या","en":"Root or soil trouble"}'::jsonb,'{"gu":"આખો આંબો ઝાંખો પડે ત્યારે કારણ ઘણી વાર મૂળમાં હોય છે: પાણી ભરાવું, સખત જમીન કે ક્ષાર.","hi":"पूरा पेड़ मुरझाए तो कारण अक्सर जड़ में होता है: जलभराव, सख़्त मिट्टी या खारापन.","en":"When the whole tree turns pale the cause is often at the roots: waterlogging, hard soil or salt."}'::jsonb,'{"gu":["ખામણામાં પાણી ભરાતું હોય તો નિકાલ કરો","થડ પાસેની જમીનનો ફોટો મોકલો"],"hi":["थाले में पानी रुकता हो तो निकासी करें","तने के पास की मिट्टी का फ़ोटो भेजें"],"en":["Drain the basin if water stands","Send a photo of the soil near the trunk"]}'::jsonb,true),
('hopper','hopper-powdery-mildew','{"gu":"મધિયો (હોપર)","hi":"फुदका (हॉपर)","en":"Mango hopper"}'::jsonb,'{"gu":"મોર પર ચીકાશ અને નાનાં ઊડતાં જીવડાં તેની નિશાની છે.","hi":"बौर पर चिपचिपाहट और उड़ते कीड़े इसकी निशानी है.","en":"Sticky flowers and tiny jumping insects point to it."}'::jsonb,'{"gu":["મોર પૂરો ખીલે તે પહેલાં ભલામણ મુજબ પગલાં લો","આંબાની અંદર હવા-પ્રકાશ જાય તેવી છટણી"],"hi":["बौर पूरा खिलने से पहले सिफ़ारिश के अनुसार कदम उठाएँ","पेड़ के अंदर हवा-रोशनी जाए, ऐसी छँटाई"],"en":["Act before full bloom, as recommended","Prune so air and light reach inside"]}'::jsonb,false),
('mildew','hopper-powdery-mildew','{"gu":"ભૂકી છારો","hi":"खर्रा (चूर्णिल आसिता)","en":"Powdery mildew"}'::jsonb,'{"gu":"મોર પર સફેદ ભૂકી, ખાસ કરીને ઠંડી રાત અને ઝાકળમાં.","hi":"बौर पर सफ़ेद पाउडर, ख़ासकर ठंडी रात और ओस में.","en":"White powder on flowers, especially with cold nights and dew."}'::jsonb,'{"gu":["મોર નીકળવાની શરૂઆતમાં ભલામણ કરેલી દવા, લેબલ મુજબ","રોજ મોર તપાસો, ઝાકળવાળા દિવસોમાં ખાસ"],"hi":["बौर निकलते ही सुझाई गई दवा, लेबल के अनुसार","रोज़ बौर जाँचें, ओस वाले दिनों में ख़ास"],"en":["A recommended spray as panicles emerge, as per label","Check panicles daily, especially on dewy days"]}'::jsonb,false),
('flush','flowering','{"gu":"મોરને બદલે નવી ફૂટ","hi":"बौर की जगह नई फुटान","en":"Leaves instead of flowers"}'::jsonb,'{"gu":"ઠંડીમાં પિયત ચાલુ રહે કે ફૂટ મોડી પાકે તો આંબો મોરને બદલે પાન કાઢે છે.","hi":"ठंड में सिंचाई चालू रहे या फुटान देर से पके तो पेड़ बौर की जगह पत्ते निकालता है.","en":"If watering continues in winter or the flush matures late, the tree makes leaves instead of flowers."}'::jsonb,'{"gu":["ફળ આપતા આંબાને ફૂલ આવે ત્યાં સુધી પિયત બંધ","આવતા વર્ષે ઉતાર પછી તરત છટણી અને ખોરાક"],"hi":["फल देने वाले पेड़ों में बौर आने तक सिंचाई बंद","अगले साल तुड़ाई के तुरंत बाद छँटाई और खुराक"],"en":["No irrigation for bearing trees until flowering","Next year, prune and feed right after harvest"]}'::jsonb,false),
('waterOn','flowering','{"gu":"હાલ પિયત ચાલુ છે","hi":"अभी सिंचाई चालू है","en":"Watering is on now"}'::jsonb,'{"gu":"ઑક્ટોબરથી ફૂલ આવે ત્યાં સુધી મોટા આંબાને થોડી ખેંચ જોઈએ.","hi":"अक्टूबर से बौर आने तक बड़े पेड़ों को थोड़ा खिंचाव चाहिए.","en":"From October until flowering, bearing trees need mild water stress."}'::jsonb,'{"gu":["મોટા આંબાનું પિયત ધીમે ધીમે બંધ કરો","નાના છોડને જરૂર પૂરતું પાણી આપતા રહો"],"hi":["बड़े पेड़ों की सिंचाई धीरे-धीरे बंद करें","छोटे पौधों को ज़रूरत भर पानी देते रहें"],"en":["Slowly stop watering the bearing trees","Keep watering young plants as needed"]}'::jsonb,false),
('reserves','alternate-bearing','{"gu":"આંબાનો સંગ્રહેલો ખોરાક ખૂટ્યો","hi":"पेड़ का जमा भोजन ख़त्म","en":"Tree reserves used up"}'::jsonb,'{"gu":"ભરપૂર પાક પછી નવી ફૂટ ઓછી આવે છે, તેથી બીજા વર્ષે મોર ઓછો.","hi":"भरपूर फसल के बाद नई फुटान कम आती है, इसलिए अगले साल बौर कम.","en":"After a heavy crop the tree makes less new growth, so it flowers less next year."}'::jsonb,'{"gu":["ઉતાર પછી તરત છટણી અને સેન્દ્રિય ખાતર","ચોમાસાની નવી ફૂટને જીવાતથી બચાવો"],"hi":["तुड़ाई के तुरंत बाद छँटाई और जैविक खाद","बरसात की नई फुटान को कीटों से बचाएँ"],"en":["Prune and give organic manure right after harvest","Protect the monsoon flush from pests"]}'::jsonb,false),
('water','fruit-drop','{"gu":"પાણીની ખેંચ કે ગરમીથી ફળ ખરે","hi":"पानी की कमी या गर्मी से फल गिरना","en":"Fruit drop from water stress or heat"}'::jsonb,'{"gu":"લખોટી કે મોટાં ફળ ખરે ત્યારે કારણ મોટે ભાગે અનિયમિત પાણી અને ગરમ પવન હોય છે.","hi":"कंचे या बड़े फल गिरें तो कारण अक्सर अनियमित पानी और गर्म हवा होता है.","en":"When marble-size or bigger fruit drops, irregular water and hot winds are the usual cause."}'::jsonb,'{"gu":["ફળ વટાણા જેવડાં થાય પછી હળવું, નિયમિત પિયત","ખામણામાં મલ્ચિંગ કરો"],"hi":["फल मटर जितने होने के बाद हल्की, नियमित सिंचाई","थाले में मल्चिंग करें"],"en":["Light, regular irrigation once fruits are pea-sized","Mulch the basin"]}'::jsonb,false),
('natural','fruit-drop','{"gu":"શરૂઆતનું ખરણ કુદરતી છે","hi":"शुरुआती फल गिरना प्राकृतिक है","en":"Early drop is natural"}'::jsonb,'{"gu":"રાઈ-વટાણા જેવડાં ફળ મોટા પ્રમાણમાં ખરે તે સામાન્ય છે.","hi":"सरसों-मटर जितने फल बड़ी मात्रा में गिरना सामान्य है.","en":"Heavy drop of mustard to pea-size fruit is normal."}'::jsonb,'{"gu":["મોરના સમયે મધિયો અને છારો કાબૂમાં રાખો","પૂરા ખીલેલા મોર પર જંતુનાશક ન છાંટો"],"hi":["बौर के समय फुदका और खर्रा नियंत्रित रखें","पूरे खिले बौर पर कीटनाशक न छिड़कें"],"en":["Keep hoppers and mildew in check at flowering","Do not spray insecticide on open flowers"]}'::jsonb,false),
('small','fruit-drop','{"gu":"ફળના વિકાસ વખતે પાણી-ખોરાક ઓછો","hi":"फल बढ़ते समय पानी-खुराक कम","en":"Too little water or food while fruit grows"}'::jsonb,'{"gu":"ફળ મોટાં થવાના સમયે પાણી અને પોષણ ન મળે તો ફળ નાનાં રહે છે.","hi":"फल बढ़ने के समय पानी और पोषण न मिले तो फल छोटे रहते हैं.","en":"Fruit stays small when water and nutrition run short as it grows."}'::jsonb,'{"gu":["માર્ચથી મે સુધી નિયમિત પિયત","જમીનની ચકાસણી પ્રમાણે ખાતર"],"hi":["मार्च से मई तक नियमित सिंचाई","मिट्टी जाँच के अनुसार खाद"],"en":["Regular irrigation from March to May","Feed according to a soil test"]}'::jsonb,false),
('micro','flowering','{"gu":"સૂક્ષ્મ તત્વોની ઉણપ","hi":"सूक्ष्म पोषक तत्वों की कमी","en":"Micronutrient shortage"}'::jsonb,'{"gu":"નવાં પાન પીળાં હોય તો ઝિંક કે આયર્ન જેવાં તત્વોની ઉણપ હોઈ શકે.","hi":"नई पत्तियाँ पीली हों तो ज़िंक या आयरन जैसे तत्वों की कमी हो सकती है.","en":"Yellow new leaves can mean a shortage of zinc or iron."}'::jsonb,'{"gu":["પાન અને જમીનની ચકાસણી કરાવો","નવાં પાનનો નજીકનો ફોટો મોકલો"],"hi":["पत्ती और मिट्टी की जाँच कराएँ","नई पत्तियों का नज़दीकी फ़ोटो भेजें"],"en":["Get a leaf and soil test","Send a close photo of new leaves"]}'::jsonb,false),
('feed','alternate-bearing','{"gu":"આંબાને ખોરાક ઓછો","hi":"पेड़ को खुराक कम","en":"The tree is underfed"}'::jsonb,'{"gu":"જૂનાં, નીચેનાં પાન પીળાં થાય તે ઘણી વાર ખોરાકની ઉણપ બતાવે છે.","hi":"पुरानी, नीचे की पत्तियाँ पीली होना अक्सर खुराक की कमी दिखाता है.","en":"Old, lower leaves turning yellow often means the tree is short of food."}'::jsonb,'{"gu":["ઉતાર પછી સેન્દ્રિય ખાતર અને ભલામણ મુજબ ખાતર","જમીનની ચકાસણી કરાવો"],"hi":["तुड़ाई के बाद जैविक खाद और सिफ़ारिश अनुसार उर्वरक","मिट्टी की जाँच कराएँ"],"en":["Organic manure and recommended fertiliser after harvest","Get a soil test"]}'::jsonb,false),
('cultar','cultar','{"gu":"વર્ષોથી Cultar નો ભાર","hi":"सालों से कल्टार का बोझ","en":"Years of Cultar"}'::jsonb,'{"gu":"દર વર્ષે Cultar થી ડાળીઓ ટૂંકી અને આંબો નબળો પડી શકે, ખાસ કરીને ખોરાક ઓછો હોય ત્યારે.","hi":"हर साल कल्टार से डालियाँ छोटी और पेड़ कमज़ोर हो सकता है, ख़ासकर कम खुराक में.","en":"Cultar every year can shorten shoots and weaken trees, especially when underfed."}'::jsonb,'{"gu":["ડોઝ દર વર્ષે ન વધારો; નિષ્ણાતની સલાહ લો","મૂળ અને જમીનને ટેકો આપો"],"hi":["खुराक हर साल न बढ़ाएँ; विशेषज्ञ से सलाह लें","जड़ और मिट्टी को सहारा दें"],"en":["Do not raise the dose each year; ask an expert","Support the roots and soil"]}'::jsonb,false),
('soilLife','cultar','{"gu":"જમીનમાં ઉપયોગી જીવાણુ ઓછા","hi":"मिट्टी में उपयोगी सूक्ष्मजीव कम","en":"Low soil life"}'::jsonb,'{"gu":"ફૂગનાશક, નીંદણનાશક અને જંતુનાશકનો વારંવાર ઉપયોગ જમીનના ઉપયોગી જીવાણુ ઘટાડી શકે.","hi":"फफूंदनाशक, खरपतवारनाशक और कीटनाशक का बार-बार उपयोग मिट्टी के उपयोगी सूक्ष्मजीव घटा सकता है.","en":"Frequent fungicides, weedicides and insecticides can reduce useful soil microbes."}'::jsonb,'{"gu":["સેન્દ્રિય ખાતર અને જૈવિક ખાતરથી જમીન જીવંત કરો","જરૂર વગર દવા ન નાખો"],"hi":["जैविक खाद और जैव उर्वरक से मिट्टी जीवित करें","बिना ज़रूरत दवा न डालें"],"en":["Bring soil back to life with manure and biofertilisers","Avoid sprays you do not need"]}'::jsonb,false),
('healthy','flowering','{"gu":"બગીચો સારી સ્થિતિમાં","hi":"बाग़ अच्छी स्थिति में","en":"Orchard looks fine"}'::jsonb,'{"gu":"તમે કોઈ મોટી તકલીફ નથી જણાવી.","hi":"आपने कोई बड़ी समस्या नहीं बताई.","en":"You did not report a major problem."}'::jsonb,'{"gu":["મહિના પ્રમાણે માવજત ચાલુ રાખો","મોરના સમયે રોજ તપાસ"],"hi":["महीने के अनुसार देखभाल जारी रखें","बौर के समय रोज़ जाँच"],"en":["Keep up month-by-month care","Check daily at flowering"]}'::jsonb,false)
